package derive

import (
	"fmt"
	"math/big"

	"github.com/ethereum-optimism/optimism/op-core/predeploys"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/common/hexutil"
	"github.com/ethereum/go-ethereum/core/types"
	"github.com/ethereum/go-ethereum/crypto"
)

var (
	// L1Block Parameters
	deployJovianL1BlockSource      = UpgradeDepositSource{Intent: "Jovian: L1 Block Deployment"}
	updateJovianL1BlockProxySource = UpgradeDepositSource{Intent: "Jovian: L1 Block Proxy Update"}
	L1BlockJovianDeployerAddress   = common.HexToAddress("0x4210000000000000000000000000000000000006")
	jovianL1BlockAddress           = crypto.CreateAddress(L1BlockJovianDeployerAddress, 0)

	// Bytecode generated from commit 773798a67678ab28c3ef7ee3405f25c04616af19
	l1BlockJovianDeploymentBytecode = common.FromHex("")

	// Gas Price Oracle Parameters
	deployJovianGasPriceOracleSource    = UpgradeDepositSource{Intent: "Jovian: Gas Price Oracle Deployment"}
	updateJovianGasPriceOracleSource    = UpgradeDepositSource{Intent: "Jovian: Gas Price Oracle Proxy Update"}
	GasPriceOracleJovianDeployerAddress = common.HexToAddress("0x4210000000000000000000000000000000000007")
	jovianGasPriceOracleAddress         = crypto.CreateAddress(GasPriceOracleJovianDeployerAddress, 0)

	// Bytecodes
	// GPO from commit 773798a67678ab28c3ef7ee3405f25c04616af19
	gasPriceOracleJovianDeploymentBytecode = common.FromHex("")

	// Enable Jovian Parameters
	enableJovianSource = UpgradeDepositSource{Intent: "Jovian: Gas Price Oracle Set Jovian"}
	enableJovianInput  = crypto.Keccak256([]byte("setJovian()"))[:4]
)

func DAFootprintNetworkUpgradeTransactions() ([]hexutil.Bytes, error) {
	deployL1Block, err := types.NewTx(&types.DepositTx{
		SourceHash:          deployJovianL1BlockSource.SourceHash(),
		From:                L1BlockJovianDeployerAddress,
		To:                  nil,
		Mint:                big.NewInt(0),
		Value:               big.NewInt(0),
		Gas:                 447_315,
		IsSystemTransaction: false,
		Data:                l1BlockJovianDeploymentBytecode,
	}).MarshalBinary()
	if err != nil {
		return nil, fmt.Errorf("build tx to deploy L1 block transaction: %w", err)
	}

	updateL1BlockProxy, err := types.NewTx(&types.DepositTx{
		SourceHash:          updateJovianL1BlockProxySource.SourceHash(),
		From:                common.Address{},
		To:                  &predeploys.L1BlockAddr,
		Mint:                big.NewInt(0),
		Value:               big.NewInt(0),
		Gas:                 50_000,
		IsSystemTransaction: false,
		Data:                upgradeToCalldata(jovianL1BlockAddress),
	}).MarshalBinary()
	if err != nil {
		return nil, fmt.Errorf("build tx to the update L1 block proxy: %w", err)
	}

	return []hexutil.Bytes{deployL1Block, updateL1BlockProxy}, nil
}

func OperatorFeeFixUpgradeTransactions() ([]hexutil.Bytes, error) {
	upgradeTxns := make([]hexutil.Bytes, 0, 8)

	// Deploy Gas Price Oracle transaction
	deployGasPriceOracle, err := types.NewTx(&types.DepositTx{
		SourceHash:          deployJovianGasPriceOracleSource.SourceHash(),
		From:                GasPriceOracleJovianDeployerAddress,
		To:                  nil,
		Mint:                big.NewInt(0),
		Value:               big.NewInt(0),
		Gas:                 1_750_714,
		IsSystemTransaction: false,
		Data:                gasPriceOracleJovianDeploymentBytecode,
	}).MarshalBinary()

	if err != nil {
		return nil, err
	}

	upgradeTxns = append(upgradeTxns, deployGasPriceOracle)

	// Deploy Gas Price Oracle Proxy upgrade transaction
	updateGasPriceOracleProxy, err := types.NewTx(&types.DepositTx{
		SourceHash:          updateJovianGasPriceOracleSource.SourceHash(),
		From:                common.Address{},
		To:                  &predeploys.GasPriceOracleAddr,
		Mint:                big.NewInt(0),
		Value:               big.NewInt(0),
		Gas:                 50_000,
		IsSystemTransaction: false,
		Data:                upgradeToCalldata(jovianGasPriceOracleAddress),
	}).MarshalBinary()

	if err != nil {
		return nil, err
	}

	upgradeTxns = append(upgradeTxns, updateGasPriceOracleProxy)

	// Enable Jovian transaction
	enableJovian, err := types.NewTx(&types.DepositTx{
		SourceHash:          enableJovianSource.SourceHash(),
		From:                L1InfoDepositerAddress,
		To:                  &predeploys.GasPriceOracleAddr,
		Mint:                big.NewInt(0),
		Value:               big.NewInt(0),
		Gas:                 90_000,
		IsSystemTransaction: false,
		Data:                enableJovianInput,
	}).MarshalBinary()

	if err != nil {
		return nil, err
	}

	upgradeTxns = append(upgradeTxns, enableJovian)

	return upgradeTxns, nil
}

func JovianNetworkUpgradeTransactions(IsDAFootprintBlockLimit, IsOperatorFeeFix bool) ([]hexutil.Bytes, error) {
	upgradeTxs := make([]hexutil.Bytes, 0)

	if IsDAFootprintBlockLimit {
		txs, err := DAFootprintNetworkUpgradeTransactions()
		if err != nil {
			return nil, err
		}
		upgradeTxs = append(upgradeTxs, txs...)
	}

	if IsOperatorFeeFix {
		txs, err := OperatorFeeFixUpgradeTransactions()
		if err != nil {
			return nil, err
		}
		upgradeTxs = append(upgradeTxs, txs...)
	}

	return upgradeTxs, nil
}
